import {
    Table,
    BooleanColumn,
    DocumentIdColumn,
    GenericColumn,
    JsonColumn,
    ReferenceColumn,
    StringColumn,
    TranslatedFieldColumn,
} from '../../db'

export const sys_ux_page_registry = Table({
    actions: {
        read: true,
        update: true,
        delete: true,
        create: true,
    },
    allowClientScripts: false,
    allowNewFields: false,
    allowUiActions: false,
    allowWebServiceAccess: true,
    attributes: {
        'all_tables.text_index_translations': true,
        no_text_index: true,
        update_synch: true,
    },
    display: 'title',
    extends: 'sys_metadata',
    label: 'UX Application',
    name: 'sys_ux_page_registry',
    schema: {
        // Was StringColumn({}). The dictionary entry is translated_field. TranslatedFieldColumn takes
        // the same config and yields the same string value type, so nothing a developer writes changes.
        title: TranslatedFieldColumn({
            maxLength: 255,
        }),
        active: BooleanColumn({
            default: true,
            maxLength: 40,
        }),
        // Was TableNameColumn: the dictionary entry is table_list, which has no dedicated column type.
        // Backward compatible — same string value type as before.
        admin_panel_table: GenericColumn({
            attributes: {
                includeNone: true,
                tableChoicesScript: 'UxPageRegistryAdminTableChoices',
            },
            columnType: 'table_list',
            label: 'Admin panel table',
            maxLength: 40,
        }),
        admin_panel: DocumentIdColumn({
            dependent: 'admin_panel_table',
            label: 'Admin panel',
            maxLength: 32,
        }),
        parent_app: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            maxLength: 32,
            referenceTable: 'sys_ux_app',
        }),
        // `mandatory: true` on the instance, ignored here for backward compatibility so we don't
        // break apps that create these records through the Record API.
        path: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            label: 'URL path',
            maxLength: 255,
        }),
        root_macroponent: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'App Shell UI',
            maxLength: 32,
            referenceTable: 'sys_ux_macroponent',
            referenceQual: 'category=chrome',
            useReferenceQualifier: 'simple',
        }),
        page: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            maxLength: 32,
            referenceTable: 'sys_ux_page',
        }),
        auth_routes: JsonColumn({
            label: [
                {
                    hint: 'JSON Data for Authentication/Authorization public routes',
                    label: 'Auth Routes',
                    plural: 'Auth Routes',
                },
            ],
            maxLength: 8000,
        }),
    },
    textIndex: true,
})
